/**
 * Viewer UX slice S6 (docs/PRD_VIEWER_UX.md 4.1, 6.3, 6.4, 12.2): Runs home lists what needs the operator, what runs and
 * what finished in the last seven days across every project; the project page groups the same rows by feature; the
 * feature page keeps its `run-list` rows and folds the current definition away; and the run page reads the served
 * `activity` (a live question record, a pane, a stopped controller) and `run_dir`. These tests assert only on the
 * `ux-lists` runs, since the combined candidate also lists other slices' runs, and fix the page clock at `LISTS_NOW`.
 */
import { test, expect, type Locator, type Page } from '@playwright/test'
import { currentCrumb } from '../helpers.ts'
import { EMPTY_PROJECT, PROJECT } from './fixtures.ts'
import {
  ANSWERED_QUESTION, LISTS_FEATURE, LISTS_NOW, mockRunDir, RUN_LISTS_ANSWERED, RUN_LISTS_APPROVAL, RUN_LISTS_ASKING, RUN_LISTS_FAILED,
  RUN_LISTS_FAILED_EARLIER, RUN_LISTS_LIVE, RUN_LISTS_OLD, RUN_LISTS_STOPPED, UX_LISTS_WORKFLOW_ID, UX_LISTS_WORKFLOW_NAME,
} from './fixtures/ux-lists.ts'
import { attach, expectNoExecutionControls, installHooks, phase, projectsUrl, runUrl, workflowUrl } from './support.ts'

installHooks()

const OWN_RUNS = [RUN_LISTS_ASKING, RUN_LISTS_ANSWERED, RUN_LISTS_APPROVAL, RUN_LISTS_LIVE, RUN_LISTS_STOPPED, RUN_LISTS_FAILED, RUN_LISTS_FAILED_EARLIER, RUN_LISTS_OLD]
const listsRunUrl = (runId: string) => runUrl(runId, undefined, UX_LISTS_WORKFLOW_ID)
const row = (scope: Locator, runId: string) => scope.locator(`a[data-run-id="${runId}"]`)
/** The run ids a section lists, in order, limited to this workflow's runs. */
const ownIds = (section: Locator) => section.locator('a[data-run-id]').evaluateAll(
  (links, own) => links.map(link => link.getAttribute('data-run-id')).filter(id => id !== null && own.includes(id)), OWN_RUNS)
const liveStatus = (page: Page) => page.getByTestId('live-status')
const banner = (page: Page) => page.getByTestId('run-now')

test(`[scenario:runs-home] Runs home lists Needs you, Running and Recent across projects; the project page groups rows by feature; the feature page folds its definition (${phase})`, async ({ page }, testInfo) => {
  await page.clock.setFixedTime(LISTS_NOW)
  await page.goto(projectsUrl)
  await expect(currentCrumb(page)).toHaveText('Projects')
  await expect(page.getByTestId('projects-info')).toContainText('Read-only')
  const needs = page.getByTestId('needs-you')
  const running = page.getByTestId('running-runs')
  const recent = page.getByTestId('recent-runs')

  // Needs you: grouped by what waits (served activity.attention.kind), each row one link in an li, named by its run id first.
  await expect(row(needs, RUN_LISTS_ASKING)).toHaveAttribute('data-attention', 'question')
  await expect(row(needs, RUN_LISTS_ANSWERED)).toHaveAttribute('data-attention', 'pane')
  await expect(row(needs, RUN_LISTS_APPROVAL)).toHaveAttribute('data-attention', 'approval')
  await expect(row(needs, RUN_LISTS_APPROVAL)).toHaveAttribute('data-status', 'awaiting_approval')
  for (const runId of [RUN_LISTS_ASKING, RUN_LISTS_ANSWERED, RUN_LISTS_APPROVAL]) {
    await expect(needs.getByRole('link', { name: new RegExp(`^${runId}(?:\\s|$)`) })).toHaveCount(1)
    expect(await row(needs, runId).evaluate(link => link.parentElement?.tagName)).toBe('LI')
  }
  await expect(row(needs, RUN_LISTS_ASKING)).toContainText('ui asked a question')
  // The live question record answered ui's question: the run waits on adapter's pane, never on a question.
  await expect(row(needs, RUN_LISTS_ANSWERED)).toContainText('adapter needs attention in its pane')
  await expect(row(needs, RUN_LISTS_ANSWERED)).not.toContainText('asked a question')
  await expect(row(needs, RUN_LISTS_APPROVAL)).toContainText('Freeze worker handoffs awaits your decision')
  // Titles follow the rule: the generic definition name gives the latest run's feature.
  await expect(row(needs, RUN_LISTS_ASKING)).toContainText(LISTS_FEATURE)
  await expect(row(needs, RUN_LISTS_ASKING)).toContainText(PROJECT.name)
  await expect(needs).not.toContainText(UX_LISTS_WORKFLOW_NAME)

  // Running: the other live runs, never repeated in another section.
  await expect(row(running, RUN_LISTS_LIVE)).toHaveAttribute('data-status', 'running')
  await expect(row(running, RUN_LISTS_STOPPED)).toHaveAttribute('data-status', 'running')
  await expect(row(running, RUN_LISTS_LIVE)).not.toHaveAttribute('data-attention', /.+/)
  await expect(running.getByRole('link', { name: new RegExp(`^${RUN_LISTS_LIVE}(?:\\s|$)`) })).toHaveCount(1)
  for (const runId of [RUN_LISTS_ASKING, RUN_LISTS_ANSWERED, RUN_LISTS_APPROVAL]) await expect(row(running, runId)).toHaveCount(0)

  // Recent: finished in the last seven days, newest first, with the finish time and the duration from the served activity.
  expect(await ownIds(recent)).toEqual([RUN_LISTS_FAILED, RUN_LISTS_FAILED_EARLIER])
  const failed = row(recent, RUN_LISTS_FAILED)
  await expect(failed).toHaveAttribute('data-status', 'failed')
  await expect(failed).toContainText('Failed at Verify ui')
  await expect(failed).toContainText('52m51s')
  await expect(failed.locator('time[datetime="2026-03-19T09:52:51Z"]').first()).toHaveText('yesterday 09:52')
  await expect(recent.getByRole('link', { name: new RegExp(`^${RUN_LISTS_FAILED}(?:\\s|$)`) })).toHaveCount(1)
  // A run that finished ten days ago is not on Runs home at all.
  await expect(page.locator(`a[data-run-id="${RUN_LISTS_OLD}"]`)).toHaveCount(0)
  for (const runId of OWN_RUNS) expect(await page.locator(`a[data-run-id="${runId}"]`).count(), runId).toBeLessThanOrEqual(1)

  // Compact project cards, one link each.
  const projects = page.getByTestId('projects-list')
  await expect(projects.getByRole('link')).toHaveCount(2)
  await expect(projects.getByRole('link', { name: new RegExp(`^${PROJECT.name}`) })).toContainText(/\d+ features/)
  await expect(projects.getByRole('link', { name: new RegExp(`^${EMPTY_PROJECT.name}`) })).toContainText('0 features')
  await expectNoExecutionControls(page)
  await attach(page, testInfo, 'runs-home')

  // At 390 px each row stacks into short lines, the whole row is the tap target, and nothing scrolls sideways.
  await page.setViewportSize({ width: 390, height: 844 })
  const narrow = row(recent, RUN_LISTS_FAILED)
  const id = await narrow.locator('.run-row-id').boundingBox()
  const when = await narrow.locator('.run-row-when').boundingBox()
  const detail = await narrow.locator('.run-row-detail').boundingBox()
  expect(id && when && detail).toBeTruthy()
  expect(when!.y).toBeGreaterThanOrEqual(id!.y + id!.height - 1)
  expect(detail!.y).toBeGreaterThanOrEqual(id!.y + id!.height - 1)
  expect((await narrow.boundingBox())!.height).toBeGreaterThanOrEqual(44)
  expect(await (page.evaluate('document.documentElement.scrollWidth - document.documentElement.clientWidth') as Promise<number>)).toBeLessThanOrEqual(0)
  await page.setViewportSize({ width: 1280, height: 720 })

  // The project page: the same rows grouped by feature; a group header links to the feature's runs, and the old run stays here.
  await page.getByTestId('projects-list').getByRole('link', { name: new RegExp(`^${PROJECT.name}`) }).click()
  await expect(currentCrumb(page)).toHaveText(PROJECT.name)
  const groups = page.getByTestId('workflows-list')
  const group = groups.locator(`[data-workflow-id="${UX_LISTS_WORKFLOW_ID}"]`)
  const header = group.getByRole('link', { name: new RegExp(`^${LISTS_FEATURE}`) })
  await expect(header).toContainText(`${UX_LISTS_WORKFLOW_ID} · ${OWN_RUNS.length} runs`)
  await expect(row(group, RUN_LISTS_OLD)).toHaveAttribute('data-status', 'failed')
  await expect(row(group, RUN_LISTS_ASKING)).toHaveAttribute('data-attention', 'question')
  await expect(row(group, RUN_LISTS_ASKING).locator('.run-row-glyph')).toHaveText('?')
  expect((await ownIds(group)).sort()).toEqual([...OWN_RUNS].sort())

  // The feature page: the same rows in run-list, and the current definition closed below them.
  await header.click()
  await expect(page).toHaveURL(new RegExp(`${workflowUrl(PROJECT.project_id, UX_LISTS_WORKFLOW_ID)}$`))
  await expect(currentCrumb(page)).toHaveText(LISTS_FEATURE)
  const runList = page.getByTestId('run-list')
  await expect(runList.locator('li')).toHaveCount(OWN_RUNS.length)
  await expect(runList.getByRole('link', { name: new RegExp(`^${RUN_LISTS_OLD}(?:\\s|$)`) })).toHaveCount(1)
  const definition = page.getByTestId('current-definition')
  await expect(definition).toHaveJSProperty('tagName', 'DETAILS')
  await expect(definition).toHaveJSProperty('open', false)
  await expect(page.getByRole('group', { name: `Current definition graph of ${UX_LISTS_WORKFLOW_NAME}` })).toHaveCount(0)
  await definition.locator('summary').click()
  await expect(page.getByRole('group', { name: `Current definition graph of ${UX_LISTS_WORKFLOW_NAME}` })).toBeVisible()
  await expectNoExecutionControls(page)
})

test(`[scenario:served-activity] The run page reads the served activity: a live question record, the run directory and the controller liveness (${phase})`, async ({ page }, testInfo) => {
  test.setTimeout(90_000)
  await page.clock.install({ time: new Date(LISTS_NOW) })

  // The export still shows ui's question 1 waiting; the live ui.questions.json records it answered, so adapter's pane is what waits.
  await page.goto(listsRunUrl(RUN_LISTS_ANSWERED))
  await expect(banner(page)).toHaveAttribute('data-situation', 'pane_attention')
  await expect(page.getByTestId('now-headline')).toContainText('adapter needs attention in its pane')
  await expect(banner(page)).not.toContainText(ANSWERED_QUESTION)

  // A question only the live record holds waits on the operator.
  await page.goto(listsRunUrl(RUN_LISTS_ASKING))
  await expect(banner(page)).toHaveAttribute('data-situation', 'question')
  await expect(page.getByTestId('now-headline')).toContainText('Waiting on you: ui asked a question')
  // The RUN= line makes the commands paste-ready when the run directory is served (worker-phase mocks); the candidate
  // phase's temporary roots lie outside $HOME, so it serves none and the block keeps the $RUN legend only.
  const runLine = banner(page).getByTestId('command-run')
  if (phase === 'worker') {
    await expect(runLine.getByTestId('run-dir-command')).toHaveText(`RUN=${mockRunDir(RUN_LISTS_ASKING)}`)
    await expect(runLine.getByRole('button')).toHaveText('Copy')
  } else {
    await expect(banner(page).getByTestId('now-command').first()).toBeVisible()
    await expect(runLine).toHaveCount(0)
  }
  await expect(banner(page).getByTestId('now-command').first()).toContainText('"$RUN"')

  // The live chip: `controller running` from the worker-phase mock; the candidate phase's seeded PID has no process.
  if (phase === 'worker') {
    await page.goto(listsRunUrl(RUN_LISTS_LIVE))
    await expect(liveStatus(page)).toHaveAttribute('data-controller', 'running')
    await expect(liveStatus(page)).toContainText('controller running')
  }

  // `not_running` is believed only once it has held for 15 s of polls: a single reading can be a checkpoint hand-over.
  await page.goto(listsRunUrl(RUN_LISTS_STOPPED))
  await expect(liveStatus(page)).toHaveAttribute('data-state', 'live')
  await expect(banner(page)).toHaveAttribute('data-situation', 'running')
  await expect(liveStatus(page)).not.toContainText('controller not running')
  await page.clock.fastForward('00:06')
  await expect(liveStatus(page)).toHaveAttribute('data-state', 'live')
  await expect(liveStatus(page)).not.toContainText('controller not running')
  await page.clock.fastForward('00:10')
  await expect(liveStatus(page)).toContainText('▲ controller not running')
  await expect(liveStatus(page)).toHaveAttribute('data-controller', 'not_running')
  // Then, while the run reads running, the banner says the controller stopped (rule 5 case c).
  await expect(banner(page)).toHaveAttribute('data-situation', 'interrupted')
  await expect(page.getByTestId('now-headline')).toContainText('the controller is not running')
  await expect(banner(page).getByTestId('now-command').first()).toContainText('"$PY" -m workflow automatic "$RUN" --live')
  await expectNoExecutionControls(page)
  await attach(page, testInfo, 'served-activity')
})

/**
 * The review, challenge and controller pages' pure model (src/projects/node/panels.ts, docs/PRD_VIEWER_UX.md 4.7-4.9):
 * reviewer durations and deadlines only from served fields, the challenge headline, the handoff's wait from the launch
 * receipts, the approval's instant and wording, the integrated commit and the section index entries.
 */
import { test } from 'node:test'
import assert from 'node:assert/strict'
import type { Span } from '../../contracts/projects/triage.ts'
import type { ReviewFinding, ReviewResult, RunInputs } from '../../contracts/projects/v1.ts'
import type { WorkflowEvent } from '../../contracts/workflow/v1.ts'
import {
  approvalLine, blockingFindings, challengeHeadline, challengeSectionEntries, deadlineText, handoffWait, integratedCommit, lastStatusAt,
  reviewerDeadline, reviewerTime, reviewSectionEntries,
} from '../../src/projects/node/panels.ts'

type Challenge = NonNullable<RunInputs['challenge']>
type Worker = RunInputs['workers'][number]

const finding = (severity: ReviewFinding['severity'], disposition: ReviewFinding['disposition']): ReviewFinding => ({
  severity, disposition, message: `${severity} ${disposition}`, worker: 'ui', requirement: null, requirement_found_in: [], reviewer: 'general',
})
const span = (nodeId: string, attempt: number, start: string | null, end: string | null, source: 'event' | 'inferred' = 'event'): Span => ({
  node_id: nodeId, lane: null, attempt, start: start ? { at: start, source } : null, end: end ? { at: end, source, ...(source === 'inferred' ? { note: 'no approval event recorded' } : {}) } : null,
  ms: start && end ? Date.parse(end) - Date.parse(start) : null, status: 'succeeded', outcome: '', live: false, result_uri: null, split: null,
})
const event = (nodeId: string, sequence: number, at: string, status: WorkflowEvent['status'], message: string): WorkflowEvent => ({
  contract_version: '1.0.0', run_id: 'r', event_id: `r:${sequence}`, sequence, occurred_at: at, node_id: nodeId, attempt: 1,
  type: status ? 'status_changed' : 'log', status, message, artifact: null, result_uri: null, reused_from_attempt: null,
})
const challenge = (fields: Partial<Challenge>): Challenge => ({
  status: 'passed', attempt: 1, session_id: 's', pinned: { tasks_sha256: 'a'.repeat(64), decisions_sha256: 'b'.repeat(64), prd_sha256: null },
  concerns: [], simpler_alternative: 'x', cheap_experiment: 'y', accepted_reason: null, decided_at: '2026-03-05T08:50:49Z', attempts: 1, ...fields,
})
const p2 = (n: number) => Array.from({ length: n }, (_, index) => ({ severity: 'P2' as const, kind: 'complexity' as const, message: `note ${index}`, consequence: 'c' }))
const worker = (id: string, requested: string, started: string | null): Worker => ({
  node_id: id, launch_node_id: `launch_${id}`, role: 'frontend', required_check_kinds: [], task: { text: '', truncated: false }, prompt: null, owned_paths: [], checks: [],
  launch: { session_id: null, launch_requested_at: requested, native_started_at: started, observed_state: 'done', status: 'attached_session_available', launcher_invocations: 1 },
  completion: null, handoff: null, stop: null, questions: [],
})

test('a decided reviewer took from its launch to its accepted file; nothing is invented without a launch time', () => {
  assert.deepEqual(reviewerTime({ launched_at: '2026-03-05T09:40:00Z', accepted_at: '2026-03-05T09:43:49Z', transport: 'native' }), { kind: 'took', ms: 229_000 })
  assert.deepEqual(reviewerTime({ launched_at: null, accepted_at: '2026-03-05T09:44:10Z', transport: 'print' }), { kind: 'no_launch', print: true })
  assert.deepEqual(reviewerTime({ launched_at: null, accepted_at: null, transport: 'native' }), { kind: 'no_launch', print: false })
  // Launched but no verdict (pending or superseded): the launch time, never an elapsed time.
  assert.deepEqual(reviewerTime({ launched_at: '2026-03-05T09:40:00Z', accepted_at: null, transport: 'native' }), { kind: 'no_verdict', launchedAt: '2026-03-05T09:40:00Z' })
})

test('a reviewer deadline is its launch plus the review timeout, only with a launch time, and says when it passed', () => {
  const now = Date.parse('2026-03-05T10:14:00Z')
  const deadline = reviewerDeadline('2026-03-05T09:40:00Z', 3600, now)
  assert.deepEqual(deadline, { at: '2026-03-05T10:40:00.000Z', leftMs: 26 * 60_000, passed: false })
  assert.equal(deadlineText(deadline!, iso => iso.slice(11, 16)), 'deadline ≈10:40 (26m left)')
  const passed = reviewerDeadline('2026-03-05T09:40:00Z', 1800, now)
  assert.equal(passed?.passed, true)
  assert.equal(deadlineText(passed!, iso => iso.slice(11, 16)), 'deadline ≈10:10 (passed)')
  assert.equal(reviewerDeadline(null, 1800, now), null)
  assert.equal(reviewerDeadline('2026-03-05T09:40:00Z', null, now), null)
})

test('blocking findings are the unresolved P0 and P1; the index counts them and every finding', () => {
  const findings = [finding('P1', 'open'), finding('P0', 'accepted'), finding('P1', 'resolved'), finding('P2', 'open')]
  assert.deepEqual(blockingFindings({ findings }).map(item => item.message), ['P1 open', 'P0 accepted'])
  const review = { findings } as ReviewResult
  assert.deepEqual(reviewSectionEntries(review), [{ key: 'blocking', label: 'Blocking', count: 2 }, { key: 'review', label: 'Findings', count: 4 }])
  assert.deepEqual(reviewSectionEntries({ findings: [finding('P2', 'open')] } as ReviewResult), [{ key: 'review', label: 'Findings', count: 1 }])
  assert.deepEqual(reviewSectionEntries(null), [])
})

test('the challenge headline names the outcome, the attempt, the notes, the decision and the span over every attempt', () => {
  const spans = [span('challenge', 1, '2026-03-05T08:39:42Z', '2026-03-05T08:45:00Z'), span('challenge', 2, '2026-03-05T08:45:00Z', '2026-03-05T08:45:46Z'), span('challenge', 3, '2026-03-05T08:48:20Z', '2026-03-05T08:50:49Z')]
  assert.deepEqual(challengeHeadline(challenge({ attempt: 3, attempts: 3, concerns: p2(8) }), spans), {
    lead: 'Passed on attempt 3', notes: '8 P2 notes', decidedAt: '2026-03-05T08:50:49Z', totalMs: 667_000, attempts: 3,
  })
  assert.equal(challengeHeadline(challenge({ concerns: p2(1) }), [])?.notes, '1 P2 note')
  assert.equal(challengeHeadline(challenge({ concerns: [] }), [])?.notes, null)
  assert.equal(challengeHeadline(challenge({}), [])?.totalMs, null)
  const paused = challengeHeadline(challenge({ status: 'paused', concerns: [...p2(1), { severity: 'P1', kind: 'assumption', message: 'm', consequence: 'c' }] }), [])
  assert.equal(paused?.lead, 'Paused: the design challenge found 1 P1; no worker was launched.')
  assert.equal(paused?.notes, '1 P2 note')
  const accepted = challengeHeadline(challenge({ status: 'accepted', attempt: 2, attempts: 2, accepted_reason: 'r', concerns: [{ severity: 'P1', kind: 'assumption', message: 'm', consequence: 'c' }] }), [])
  assert.equal(accepted?.lead, 'Accepted by the operator on attempt 2 over 1 P1')
  assert.equal(challengeHeadline(challenge({ status: 'disabled', attempt: 0, attempts: 0 }), [])?.lead, 'Disabled: nothing was challenged')
  assert.deepEqual(challengeSectionEntries(challenge({ concerns: p2(8) })), [{ key: 'concerns', label: 'Concerns', count: 8 }, { key: 'alternative', label: 'Alternative & experiment' }])
  assert.deepEqual(challengeSectionEntries(challenge({})), [{ key: 'alternative', label: 'Alternative & experiment' }])
  assert.deepEqual(challengeSectionEntries(null), [])
})

test('the handoff waited from the latest launch start (native start, else the request) to the freeze', () => {
  const workers = [worker('ui', '2026-03-05T08:50:58Z', '2026-03-05T08:51:00.000Z'), worker('adapter', '2026-03-05T08:51:28Z', '2026-03-05T08:51:33.000Z')]
  assert.deepEqual(handoffWait(workers, '2026-03-05T09:19:54Z'), { ms: 1_701_000, from: '2026-03-05T08:51:33.000Z', lane: 'adapter' })
  // Without a native start, the launch request is the start.
  assert.deepEqual(handoffWait([worker('ui', '2026-03-05T09:00:00Z', null)], '2026-03-05T09:10:00Z'), { ms: 600_000, from: '2026-03-05T09:00:00Z', lane: 'ui' })
  assert.equal(handoffWait(workers, null), null)
  assert.equal(handoffWait([{ ...workers[0], launch: null }], '2026-03-05T09:19:54Z'), null)
  assert.equal(handoffWait(workers, '2026-03-05T08:00:00Z'), null)
})

test('an approval without an event is inferred at the integration and says so; the finish policy names who approved', () => {
  const inputs = { mode: 'automatic', automatic: { finish: 'verified-feature-branch' } } as RunInputs
  const inferred = [span('approval', 1, '2026-03-05T09:43:52Z', '2026-03-05T09:43:52Z', 'inferred')]
  assert.deepEqual(approvalLine(inferred, [], inputs), { at: '2026-03-05T09:43:52Z', inferred: true, how: 'approved automatically by the finish policy (verified-feature-branch)', recorded: false })
  const recorded = [event('approval', 4, '2026-03-05T10:00:00Z', 'succeeded', 'Approved')]
  assert.deepEqual(approvalLine([span('approval', 1, '2026-03-05T10:00:00Z', '2026-03-05T10:00:00Z')], recorded, { mode: 'manual', automatic: null } as RunInputs),
    { at: '2026-03-05T10:00:00Z', inferred: false, how: 'approved by the operator', recorded: true })
  assert.equal(approvalLine([], [], inputs), null)
})

test('the integrated commit is the one the integration row names, else the reviewed candidate; the last status row dates a wait', () => {
  const commit = 'c'.repeat(40)
  assert.equal(integratedCommit([event('integrate', 1, '2026-03-05T09:43:52Z', 'succeeded', `Fast-forwarded to ${commit}; no push performed`)], null), commit)
  assert.equal(integratedCommit([], { candidate_commit: 'd'.repeat(40) }), 'd'.repeat(40))
  assert.equal(integratedCommit([], null), null)
  assert.equal(lastStatusAt([event('approval', 1, '2026-03-05T10:00:00Z', 'running', 'a'), event('approval', 2, '2026-03-05T10:02:00Z', null, 'log'), event('approval', 3, '2026-03-05T10:01:00Z', 'awaiting_approval', 'b')]), '2026-03-05T10:01:00Z')
  assert.equal(lastStatusAt([]), null)
})

/**
 * The run lists' pure rules (docs/PRD_VIEWER_UX.md 4.1, 6.3, 6.4; slice S6): the workflow title rule, the Runs home
 * sections and the 7-day Recent window, row wording with and without the served `activity`, the controller suffix and its
 * 15 s debounce, and when the Now banner reads the served activity over the export.
 */
import { describe, test } from 'node:test'
import assert from 'node:assert/strict'
import { deriveNow, type ControllerReading, type Now } from '../../contracts/projects/triage.ts'
import { validateRunDetail, type RunActivity, type RunDetail, type RunSummary } from '../../contracts/projects/v1.ts'
import {
  controllerSuffix, homeSections, latestFeature, latestRun, projectFacts, readsNextPage, recordReading, RECENT_WINDOW_MS, rowSummary, rowTime,
  servedDisagreement, servedNow, workflowTitle, type ServedRun,
} from '../../src/projects/lists.ts'
import { definition, laneGraphNodes, runDetail, type NodeState } from '../project-workflows/fixtures.ts'

const NOW = Date.parse('2026-03-20T12:00:00Z')
const DAY = 24 * 60 * 60 * 1000
const iso = (time: number) => new Date(time).toISOString().replace(/\.000Z$/, 'Z')
const NODES = laneGraphNodes(['ui', 'adapter'])
const DEFINITION = definition('alpha-project', 'ux-lists', 'Feature implementation', NODES)
const LABELS = new Map(NODES.map(node => [node.node_id, node.label]))

const activity = (fields: Partial<RunActivity> = {}): RunActivity => ({
  feature: 'Runs home lists', last_activity_at: null, finished_at: null, focus: null, attention: null, waiting_questions: 0, headline: null, controller: null, ...fields,
})

function summary(runId: string, status: RunSummary['status'], fields: { created?: string; updated?: string; activity?: RunActivity | null } = {}): RunSummary {
  const base: RunSummary = {
    contract_version: '1.0.0', project_id: 'alpha-project', workflow_id: 'ux-lists', definition_revision: DEFINITION.definition_revision, run_id: runId, status,
    created_at: fields.created ?? '2026-03-19T09:00:00Z', updated_at: fields.updated ?? fields.created ?? '2026-03-19T09:00:00Z',
  }
  return fields.activity ? { ...base, contract_version: '1.5.0', activity: fields.activity } : base
}

/** A running two-lane run, as the server serves it with contract 1.5.0. */
function runningDetail(runActivity: RunActivity, states: Record<string, NodeState> = { launch_ui: { status: 'running', attempt: 1 }, launch_adapter: { status: 'running', attempt: 1 } }): RunDetail {
  const base = runDetail('lists-live', 'running', DEFINITION, '2026-03-20T11:00:00Z', '2026-03-20T11:30:00Z', states, 4)
  return validateRunDetail({ ...base, summary: { ...base.summary, contract_version: '1.5.0', activity: runActivity }, run_dir: null })
}

const served = (detail: RunDetail, controller: ControllerReading[] = []): ServedRun => ({ detail, activity: detail.summary.activity ?? null, runDir: null, controller })
const reading = (seconds: number, value: ControllerReading['value']): ControllerReading => ({ at: iso(NOW + seconds * 1000), value })

